import{_t as e,it as t,n,rt as r}from"./chunks/framework.BmT8T0yb.js";var i=JSON.parse(`{"title":"Plan View - Rally Points","description":"","frontmatter":{"qt_version":"6.12.0"},"headers":[],"relativePath":"en/qgc-user-guide/plan_view/plan_rally_points.md","filePath":"en/qgc-user-guide/plan_view/plan_rally_points.md"}`),a={name:`en/qgc-user-guide/plan_view/plan_rally_points.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="plan-view-rally-points" tabindex="-1">Plan View - Rally Points <a class="header-anchor" href="#plan-view-rally-points" aria-label="Permalink to “Plan View - Rally Points”">​</a></h1><p>Rally Points are alternative landing or loiter locations. They are typically used to provide a safer or more convenient (e.g. closer) destination than the home position in Return/RTL mode.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>If Rally Points are not supported by the connected vehicle firmware, the <strong>Rally</strong> tab shows a message saying so instead of the Rally Point options.</p></div><h2 id="rally-point-usage" tabindex="-1">Rally Point Usage <a class="header-anchor" href="#rally-point-usage" aria-label="Permalink to “Rally Point Usage”">​</a></h2><p>To create Rally Points:</p><ol><li>Navigate to the Plan View</li><li>Select the <strong>Rally</strong> tab in the <a href="./plan_view.html#plan-editor-panel">Plan Editor Panel</a>. The tab is enabled once the <a href="./plan_view.html#planned-home">planned home position</a> is set.</li><li>Click the map wherever you want rally points. <ul><li>An <strong>R</strong> marker is added for each</li><li>The currently active marker has a different color (green) and its editor is shown in the inspector below the list of rally points.</li></ul></li><li>Make any rally point active by selecting it on the map or in the list on the <strong>Rally</strong> tab: <ul><li>Move the active rally point by either dragging it on the map or editing the position fields in the inspector.</li><li>Set its altitude and altitude frame in the inspector.</li><li>Delete a rally point by pressing the delete button (trash icon) in the inspector.</li></ul></li></ol><h2 id="upload-rally-points" tabindex="-1">Upload Rally Points <a class="header-anchor" href="#upload-rally-points" aria-label="Permalink to “Upload Rally Points”">​</a></h2><p>Rally points are uploaded along with the rest of the plan using the <strong>Upload</strong> button in the <a href="./plan_view.html#file">Plan Toolbar</a>.</p>`,8)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};